package com.universe.school.dto.response; import com.universe.school.entity.SchoolVerification; import lombok.AllArgsConstructor; import lombok.Getter; import java.time.LocalDateTime; @Getter @AllArgsConstructor public class SchoolVerificationResponse { private Long verificationId; private Long schoolId; private String schoolName; private String schoolEmail; private String status; private LocalDateTime verifiedAt; private String verificationCode; public static SchoolVerificationResponse from(SchoolVerification v){return from(v,null);} public static SchoolVerificationResponse from(SchoolVerification v,String verificationCode){return new SchoolVerificationResponse(v.getId(),v.getSchool().getId(),v.getSchool().getSchoolName(),v.getSchoolEmail(),v.getStatus().name(),v.getVerifiedAt(),verificationCode);}}
